# This will check all child table rows before saving
def update_car_repair_status(doc, method):
    if doc.list_of_damage:
        all_completed = True
        for row in doc.list_of_damage:
            if row.status != "Completed":
                all_completed = False
                break

        if all_completed:
            doc.status = "Completed"
        else:
            # Optional: Keep status In Progress if not all done
            doc.status = "In Progress"

# Auto-fill Reference No from Car Repair Request
if not doc.reference_no and doc.car_repair_request:
    doc.reference_no = doc.car_repair_request

# Auto-fill Reference No from linked Car Repair Request
if doc.car_repair_request and not doc.reference_no:
    doc.reference_no = doc.car_repair_request
